-- CAB-0011: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='gabungan-rakyat-sabah' and type='alliance') then raise exception 'CAB-0011: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'CAB-0011: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('armizan-mohd-ali','gobind-singh-deo') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0011: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('papar','damansara') and slug not in ('armizan-mohd-ali','gobind-singh-deo')) then raise exception 'CAB-0011: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0011:%' and (m.source_type <> 'editorial' or e.slug not in ('armizan-mohd-ali','gobind-singh-deo') or m.import_key not like 'CAB-0011:' || e.slug || ':%')) then raise exception 'CAB-0011: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'armizan-mohd-ali','Armizan Mohd Ali','government','Minister of Domestic Trade and Cost of Living','Papar','Sabah','Armizan Mohd Ali is Minister of Domestic Trade and Cost of Living. He represents Papar, Sabah, in the Dewan Rakyat. He is affiliated with Gabungan Rakyat Sabah (GRS).','https://www.kpdn.gov.my/','/portraits/armizan-mohd-ali.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P175.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Papar", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4214"}, {"label": "GRS · Armizan (6 Oct 2026)", "url": "https://bernama.com/en/politics/news.php?id=2616296"}]'::jsonb from public.entities parent where parent.slug='gabungan-rakyat-sabah' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'gobind-singh-deo','Gobind Singh Deo','government','Minister of Digital','Damansara','Selangor','Gobind Singh Deo is Minister of Digital. He represents Damansara, Selangor, in the Dewan Rakyat. He is a member of DAP.','https://www.digital.gov.my/','/portraits/gobind-singh-deo.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P106.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Damansara", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4145"}, {"label": "DAP · current leadership", "url": "https://dapmalaysia.org/en/our-leaders/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('armizan-mohd-ali','gobind-singh-deo') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0011: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0011:armizan-mohd-ali:pjrm-30000-2026','Organise 30,000 Rahmah MADANI sales sessions in 2026','Economy','in_progress',53,'2026-12-31','2026-06-30','https://www.bernama.com/misc/rss/news.php?id=2574887','2026-06-30','https://www.bernama.com/misc/rss/news.php?id=2574887','Armizan stated the revised annual target of 30,000 Rahmah MADANI sales sessions for 2026, increased from 23,040.','His parliamentary update reports 15,881 sessions from 1 January to 30 June 2026. The bar is 15,881 ÷ 30,000 × 100 = 52.94%, rounded to 53%. It is the dated half-year delivery count, not a live November result or a measure of household savings.','2026-11-09','editorial',false from public.entities e where e.slug='armizan-mohd-ali' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0011:gobind-singh-deo:digital-economy-30-2030','Grow the digital economy’s contribution to 30% of GDP by 2030','Digital','in_progress',null,'2030-12-31','2026-08-18','https://www.bernama.com/radio/news.php?id=2595809','2026-08-18','https://www.bernama.com/radio/news.php?id=2595809','Gobind reaffirmed a 30% digital-economy contribution to GDP by 2030 and linked delivery to the national AI and MD2030 plans.','The minister described launched policies and implementation responsibilities. He cited a provisional 25.5% GDP share for 2025 while seeking confirmation of the exact figure. A sector share is not promise completion, so no numerical completion is inferred.','2026-11-09','editorial',false from public.entities e where e.slug='gobind-singh-deo' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

